async function visitLedger(stream, visitor) {
  const reader = stream.getReader();

  let accepted = 0;
  let rejected = 0;
  let stopped = false;
  let reachedEOF = false;
  let lineNumber = 0;
  let lineBuffer = "";

  const decoder = new TextDecoder();

  const processLine = async (line) => {
    lineNumber++;

    if (line.endsWith("\r")) {
      line = line.slice(0, -1);
    }

    if (line.trim() === "") {
      return;
    }

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      rejected++;
      return;
    }

    accepted++;
    const result = await visitor({ line: lineNumber, value });

    if (result === false) {
      stopped = true;
    }
  };

  const processText = async (text) => {
    lineBuffer += text;

    let start = 0;
    while (!stopped) {
      const newline = lineBuffer.indexOf("\n", start);
      if (newline === -1) {
        lineBuffer = lineBuffer.slice(start);
        return;
      }

      await processLine(lineBuffer.slice(start, newline));
      start = newline + 1;
    }

    lineBuffer = lineBuffer.slice(start);
  };

  try {
    while (!stopped) {
      const result = await reader.read();

      if (result.done) {
        reachedEOF = true;

        await processText(decoder.decode());

        if (!stopped && lineBuffer.length > 0) {
          await processLine(lineBuffer);
          lineBuffer = "";
        }

        break;
      }

      await processText(decoder.decode(result.value, { stream: true }));
    }

    return { accepted, rejected, stopped };
  } catch (error) {
    throw error;
  } finally {
    if (!reachedEOF) {
      await reader.cancel();
    }
    reader.releaseLock();
  }
}
